export const compatibility={'O-':['O-'],'O+':['O-','O+'],'A-':['O-','A-'],'A+':['O-','O+','A-','A+'],'B-':['O-','B-'],'B+':['O-','O+','B-','B+'],'AB-':['O-','A-','B-','AB-'],'AB+':['O-','O+','A-','A+','B-','B+','AB-','AB+']};
export function isCompatible(donor,recipient){return(compatibility[recipient]||[]).includes(donor)}
export function rankUnits(units,request){return units.filter(u=>u.status==='Available'&&isCompatible(u.type,request.type)).map(u=>{const days=Math.max(0,Math.ceil((new Date(u.expires)-new Date(request.today))/864e5));let score=100-days;if(u.type===request.type)score+=25;if(u.type==='O-'&&request.type!=='O-')score-=35;if(u.branch===request.branch)score+=15;return{...u,score,days}}).sort((a,b)=>b.score-a.score)}
export function forecast(current,dailyUse,incoming,days){return Math.max(0,Math.round(current+incoming-dailyUse*days))}
export function donorEligibility({age,weight,daysSinceDonation,temporaryRestriction=false}){if(age<18||age>65)return{eligible:false,reason:'Age is outside the project policy range.'};if(weight<50)return{eligible:false,reason:'Weight is below the project policy threshold.'};if(temporaryRestriction)return{eligible:false,reason:'A temporary restriction requires staff review.'};if(daysSinceDonation<56)return{eligible:false,reason:`Wait ${56-daysSinceDonation} more days before staff review.`};return{eligible:true,reason:'Basic project criteria passed. Final approval requires qualified staff.'}}
